package application

import (
	"context"
	"filesmanage/internal/domain"
)

// RecordPermissionDenial is isolated from the denied business transaction:
// a rollback must never erase evidence of a rejected authenticated attempt.
// The only supplied metadata is generated by trusted routes, not request JSON.
func (s *Service) RecordPermissionDenial(ctx context.Context, actorID, eventType, targetKind, targetID string) error {
	if actorID == "" {
		return domain.ErrInvalidInput
	}
	tx, err := s.uow.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := auditRequired(ctx, tx, domain.User{ID: actorID}, eventType, targetKind, targetID,
		"denied", map[string]any{"reason": "forbidden"}); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

func grantAuditState(grant domain.ACL) map[string]any {
	return map[string]any{
		"grantId": grant.ID, "folderId": grant.FolderID,
		"subjectKind": grant.SubjectKind, "subjectId": grant.SubjectID,
		"actions": actionNames(grant.Actions), "scopeOnly": grant.ScopeOnly,
		"expiresAt": grant.ExpiresAt,
	}
}

func shareAuditState(share domain.Share) map[string]any {
	resourceKind, resourceID := "folder", ""
	if share.FolderID != nil {
		resourceID = *share.FolderID
	}
	if share.FileID != nil {
		resourceKind, resourceID = "file", *share.FileID
	}
	return map[string]any{
		"shareId": share.ID, "resourceKind": resourceKind, "resourceId": resourceID,
		"recipientKind": share.RecipientKind, "recipientId": share.RecipientID,
		"actions": actionNames(share.Actions), "includeDescendants": share.IncludeDescendants,
		"expiresAt": share.ExpiresAt, "revoked": share.RevokedAt != nil,
	}
}
